def solve_tick_ranges(text):
    v = text.split()
    n, q = int(v[0]), int(v[1])
    ticks = [int(x) for x in v[2:2 + n]]
    first, last = {}, {}
    for i, t in enumerate(ticks):
        first.setdefault(t, i)
        last[t] = i
    top = ticks[-1] if n else None
    out = []
    for t in map(int, v[2 + n:2 + n + q]):
        if t in first:
            out.append(f'{first[t]} {last[t]}')
        elif top is None or t > top:
            out.append(f'-1 {n}')
        else:
            s = t
            while s not in first:
                s += 1
            out.append(f'-1 {first[s]}')
    return '\n'.join(out)
